import {blankDraft,uid,validCoord,fromRecognition,fromNetwork,validateDraftShape,ensureSegments,invalidateStop,normalizeCatalogue,candidatesFor,estimateTimes,inspectDraft,exportNetwork,compareRecognition,mergeRecognition,parseTime,timeString} from './editor-core.mjs';
import {meters,validateNetwork} from './core.mjs';
const $=id=>document.getElementById(id),STORAGE='p140:editor:draft:v1',CATALOGUE='p140:editor:catalogue:v1',PREVIEW='p140-editor-preview-v1';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let draft,patternIndex=0,step='source',selectedStop=0,selectedSegment=0,map,markers,roadLayers,candidateLayers,catalogue=[],history=[],mode=null,busy=false,toastTimer,routeQueue=Promise.resolve(),lastRouteRequest=0;
const current=()=>draft.patterns[patternIndex];
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
function save(){draft.updatedAt=new Date().toISOString();try{localStorage.setItem(STORAGE,JSON.stringify(draft));$('save-state').textContent='已儲存於本機 '+new Date().toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit'});}catch(e){$('save-state').textContent='本機空間不足，請下載草稿';toast('草稿無法儲存於本機，請立即下載草稿。');}}
function checkpoint(){if(draft){history.push(JSON.stringify(draft));if(history.length>10)history.shift();$('undo').disabled=false;}}
function mutate(fn,{redraw=true}={}){checkpoint();fn();save();if(redraw)render();}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function dialog(title,body,actions=[]){$('dialog-title').textContent=title;$('dialog-body').replaceChildren();if(typeof body==='string')$('dialog-body').textContent=body;else $('dialog-body').append(body);$('dialog-actions').replaceChildren();for(const action of actions){const b=document.createElement('button');b.textContent=action.text;if(action.primary)b.className='primary';b.onclick=()=>{try{action.fn();}catch(e){toast(e.message);}};$('dialog-actions').append(b);}if(!$('studio-dialog').open)$('studio-dialog').showModal();}
function ask(title,value,callback){const input=document.createElement('input');input.value=value;input.style.cssText='width:100%;padding:10px;border:1px solid #dfe5d9;border-radius:6px';input.setAttribute('aria-label',title);dialog(title,input,[{text:'取消',fn:()=>$('studio-dialog').close()},{text:'確定',primary:true,fn:()=>{if(!input.value.trim())throw Error('內容不可空白');callback(input.value.trim());$('studio-dialog').close();}}]);input.focus();}
function setStep(next){step=next;mode=null;document.querySelectorAll('[data-step]').forEach(b=>{if(b.dataset.step===next)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});document.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==next);render();$('panels').scrollTop=0;}
function renderSource(){for(const [id,key]of [['route-short','shortName'],['route-name','name'],['route-id','routeId'],['route-color','color']])$(id).value=draft[key];for(const [id,key]of [['source-title','title'],['source-url','url'],['source-date','date'],['source-notes','notes']])$(id).value=draft.source[key]||'';
 $('source-images').replaceChildren();for(const [i,src]of(draft.source.images||[]).entries()){if(!/^(editor-assets\/|data:image\/(png|jpeg|webp);base64,|https?:\/\/)/.test(src))continue;const b=document.createElement('button'),img=document.createElement('img'),label=document.createElement('span');img.src=src;img.alt='來源圖片'+(i+1);label.textContent='查看來源 '+(i+1);b.append(img,label);b.onclick=()=>{const full=document.createElement('img');full.src=src;full.alt=img.alt;dialog('官方來源圖片',full);};$('source-images').append(b);}
 $('source-warnings').innerHTML=(draft.warnings||[]).map(w=>'<p>待確認：'+escape(w)+'</p>').join('');}
function renderPatternControls(){for(const host of document.querySelectorAll('.pattern-control')){host.innerHTML='<label>行駛方向<select aria-label="選擇編輯方向">'+draft.patterns.map((p,i)=>`<option value="${i}" ${i===patternIndex?'selected':''}>${escape(p.name)} · ${p.stops.length}站</option>`).join('')+'</select></label><button class="add-direction">＋新增方向／繞駛型態</button>';host.querySelector('select').onchange=e=>{patternIndex=+e.target.value;selectedStop=0;selectedSegment=0;mode=null;render();fitMap();};host.querySelector('button').onclick=()=>ask('新增方向名稱','新方向',name=>mutate(()=>{draft.patterns.push({id:uid('pattern'),name,headsign:'',stops:[],segments:[],departures:[],sequenceConfirmed:false});patternIndex=draft.patterns.length-1;selectedStop=0;}));}}
function clearTimes(p){for(const s of p.stops){s.arrivalOffsetSec=null;s.departureOffsetSec=null;}p.timeSource='待重新估算';}
function renderStops(){const p=current(),listScroll=$('stop-list').scrollTop;$('stop-list').innerHTML=p.stops.map((s,i)=>`<div class="stop-row ${i===selectedStop?'active':''}"><span class="num">${i+1}</span><button class="stop-select" data-stop="${i}">${escape(s.name)}<small>${!s.coord?'缺少位置':s.confirmed?'✓ 已確認位置':'位置待確認'}</small></button><button class="reorder" data-move="${i},-1" aria-label="上移第${i+1}站">↑</button><button class="reorder" data-move="${i},1" aria-label="下移第${i+1}站">↓</button></div>`).join('');
 $('stop-list').scrollTop=listScroll;for(const b of $('stop-list').querySelectorAll('[data-stop]'))b.onclick=()=>{selectedStop=+b.dataset.stop;mode=null;render();const s=p.stops[selectedStop];if(s.coord)map.setView([s.coord[1],s.coord[0]],Math.max(map.getZoom(),16));};for(const b of $('stop-list').querySelectorAll('[data-move]'))b.onclick=()=>{const [i,delta]=b.dataset.move.split(',').map(Number),j=i+delta;if(j<0||j>=p.stops.length)return;mutate(()=>{[p.stops[i],p.stops[j]]=[p.stops[j],p.stops[i]];p.sequenceConfirmed=false;ensureSegments(p);clearTimes(p);selectedStop=j;});};
 $('confirm-sequence').textContent=p.sequenceConfirmed?'✓ 本方向站序已確認':'確認本方向站序';
 const s=p.stops[selectedStop];if(!s){$('stop-inspector').innerHTML='<p class="micro">新增站點後，即可進行定位。</p>';return;}
 const candidates=candidatesFor(s.name,catalogue);
 $('stop-inspector').innerHTML=`<h3>第${selectedStop+1}站 · ${escape(s.name)}</h3><div class="stop-actions"><button id="rename-stop">修改站名</button><button id="place-stop">在地圖點選位置</button><button id="delete-stop" class="danger">刪除此站</button></div><div class="coord-row"><label class="field">經度<input id="stop-lon" type="number" step="0.000001" value="${s.coord?.[0]??''}"></label><label class="field">緯度<input id="stop-lat" type="number" step="0.000001" value="${s.coord?.[1]??''}"></label></div><div class="button-row"><button id="apply-coord">套用座標</button><button id="confirm-stop" class="primary" ${!s.coord?'disabled':''}>${s.confirmed?'✓ 已確認此站':'確認此站位置'}</button></div><p class="micro">位置來源：${escape(s.coordinateSource||'尚未設定')}。去回程請分別確認道路側邊與方向。</p><h3>站牌候選 <small>（${candidates.length}）</small></h3><div id="candidate-list">${candidates.length?candidates.map((c,i)=>`<button class="candidate-card" data-candidate="${i}">${i+1}. ${escape(c.name)}<small>${escape(c.source)} · ${c.coord.map(x=>x.toFixed(6)).join(', ')}<br>${c.kind==='official'?'政府資料候選':'非官方確認位置'} · ${c.score===100?'同名比對':'近似名稱比對'}</small></button>`).join(''):'<p class="micro">目前候選庫無相符站名。可匯入政府站牌JSON、修改站名，或在地圖確認位置。</p>'}</div>`;
 $('rename-stop').onclick=()=>ask('修改站名',s.name,name=>mutate(()=>{s.name=name;s.confirmed=false;p.sequenceConfirmed=false;}));$('place-stop').onclick=()=>{mode='stop';renderMap();toast('請在地圖上點選實際站牌位置。');};$('delete-stop').onclick=()=>mutate(()=>{p.stops.splice(selectedStop,1);selectedStop=Math.max(0,selectedStop-1);ensureSegments(p);clearTimes(p);p.sequenceConfirmed=false;});
 const apply=c=>mutate(()=>{invalidateStop(p,s.id);s.coord=c;s.coordinateSource='管理者手動定位';clearTimes(p);});$('apply-coord').onclick=()=>{const lon=$('stop-lon').value,lat=$('stop-lat').value,c=[Number(lon),Number(lat)];if(!lon||!lat||!validCoord(c))return toast('請輸入有效經緯度');apply(c);};$('confirm-stop').onclick=()=>mutate(()=>{s.confirmed=true;});
 for(const b of $('candidate-list').querySelectorAll('[data-candidate]'))b.onclick=()=>chooseCandidate(candidates[+b.dataset.candidate]);
}
function chooseCandidate(c){const p=current(),s=p.stops[selectedStop];mutate(()=>{invalidateStop(p,s.id);s.coord=[...c.coord];s.candidateId=c.id;s.coordinateSource=c.source;clearTimes(p);});map.setView([c.coord[1],c.coord[0]],17);toast('已套用候選位置，請核對後按「確認此站位置」。');}
function renderRoads(){const p=current(),listScroll=$('segment-list').scrollTop;$('segment-list').innerHTML=p.segments.map((s,i)=>`<button class="segment-row ${i===selectedSegment?'active':''}" data-segment="${i}"><span>${i+1}. ${escape(p.stops[i].name)} → ${escape(p.stops[i+1].name)}</span><small>${s.locked?'🔒 ':''}${!s.path?'未產生':s.confirmed?'已確認':'待確認'}</small></button>`).join('');$('segment-list').scrollTop=listScroll;for(const b of $('segment-list').querySelectorAll('[data-segment]'))b.onclick=()=>{selectedSegment=+b.dataset.segment;mode=null;render();const s=p.segments[selectedSegment];if(s.path)map.fitBounds(s.path.map(c=>[c[1],c[0]]),{padding:[65,65],maxZoom:17});};
 const s=p.segments[selectedSegment];if(!s){$('segment-inspector').innerHTML='<p class="micro">至少需要兩個站點。</p>';return;}
 $('segment-inspector').innerHTML=`<h3>路段${selectedSegment+1} · 局部校正</h3><p class="micro">${escape(s.source||'尚未產生道路')} ${s.path?'· '+(s.path.slice(1).reduce((n,c,i)=>n+meters(s.path[i],c),0)/1000).toFixed(2)+'公里':''}</p><div class="button-row"><button id="add-via">在地圖加入必經點</button><button id="route-segment">重算此路段</button></div><div class="via-list">${s.via.length?s.via.map((c,i)=>`${i+1}. ${c.map(x=>x.toFixed(5)).join(', ')} <button data-remove-via="${i}">移除</button>`).join('<br>'):'尚未加入必經點。必經點只控制道路，不會變成公車站。'}</div><div class="button-row"><button id="confirm-segment" ${!s.path?'disabled':''}>${s.confirmed?'✓ 路段已確認':'確認此路段'}</button><button id="lock-segment" ${!s.path?'disabled':''}>${s.locked?'解除鎖定':'鎖定此路段'}</button></div>`;
 $('add-via').onclick=()=>{if(s.locked)return toast('請先解除路段鎖定');mode='via';renderMap();toast('依行駛順序，在地圖點選必經道路位置。');};$('route-segment').onclick=()=>runBusy(()=>routeSegment());$('confirm-segment').onclick=()=>mutate(()=>{s.confirmed=true;});$('lock-segment').onclick=()=>mutate(()=>{s.locked=!s.locked;});for(const b of $('segment-inspector').querySelectorAll('[data-remove-via]'))b.onclick=()=>{if(s.locked)return toast('請先解除路段鎖定');mutate(()=>{s.via.splice(+b.dataset.removeVia,1);s.path=null;s.confirmed=false;s.durationSec=null;clearTimes(p);});};
}
function renderTimes(){const p=current();$('departures').innerHTML=p.departures.slice().sort((a,b)=>parseTime(a.time)-parseTime(b.time)).map(t=>`<div class="trip-row"><b>${escape(t.time)}</b><span>${t.days.length===7?'每日':t.days.map(d=>['','一','二','三','四','五','六','日'][d]).join('、')}</span><button data-delete-trip="${escape(t.id)}" aria-label="刪除${escape(t.time)}班次">×</button></div>`).join('')||'<p class="micro">尚無班次。</p>';for(const b of $('departures').querySelectorAll('[data-delete-trip]'))b.onclick=()=>mutate(()=>{p.departures=p.departures.filter(t=>t.id!==b.dataset.deleteTrip);});
 $('time-table').innerHTML='<table class="time-table"><thead><tr><th>站名</th><th>到站／分鐘</th><th>離站／分鐘</th></tr></thead><tbody>'+p.stops.map((s,i)=>`<tr><td>${i+1}. ${escape(s.name)}</td><td><input aria-label="第${i+1}站到站累積分鐘" type="number" min="0" step="0.1" data-time="${i},arrivalOffsetSec" value="${s.arrivalOffsetSec===null?'':(s.arrivalOffsetSec/60).toFixed(2)}"></td><td><input aria-label="第${i+1}站離站累積分鐘" type="number" min="0" step="0.1" data-time="${i},departureOffsetSec" value="${s.departureOffsetSec===null?'':(s.departureOffsetSec/60).toFixed(2)}"></td></tr>`).join('')+'</tbody></table>';
 for(const input of $('time-table').querySelectorAll('[data-time]'))input.onchange=()=>{const [i,key]=input.dataset.time.split(','),val=input.value===''?null:Math.round(+input.value*60);if(val!==null&&(!Number.isFinite(val)||val<0))return toast('時間須為非負數');mutate(()=>{p.stops[+i][key]=val;const s=p.stops[+i];if(s.arrivalOffsetSec!==null&&s.departureOffsetSec!==null)s.dwellSec=Math.max(0,s.departureOffsetSec-s.arrivalOffsetSec);p.timeSource='管理者校正的估算時間；非官方途中到站時刻。';},{redraw:false});};
}
function renderValidation(){const report=inspectDraft(draft,true);$('validation-results').innerHTML=`<div class="report ${report.errors.length?'error':''}"><strong>${report.errors.length?'尚有 '+report.errors.length+' 項需要處理':'✓ 資料檢查通過，可匯出路線JSON'}</strong>${report.errors.length?'<ul>'+report.errors.map(e=>'<li>'+escape(e)+'</li>').join('')+'</ul>':''}</div><div class="warning-list">${report.warnings.map(w=>'<p>'+escape(w)+'</p>').join('')}</div>`;$('export-json').disabled=!!report.errors.length;}
function render(){if(!draft)return;patternIndex=Math.min(patternIndex,draft.patterns.length-1);selectedStop=Math.max(0,Math.min(selectedStop,current().stops.length-1));selectedSegment=Math.max(0,Math.min(selectedSegment,current().segments.length-1));renderSource();renderPatternControls();if(step==='stops')renderStops();if(step==='roads')renderRoads();if(step==='times')renderTimes();if(step==='export')renderValidation();const p=current();$('route-summary').textContent=`${draft.shortName} · ${p.name} · ${p.stops.filter(s=>s.coord).length}/${p.stops.length}站已定位`;$('catalogue-status').textContent=catalogue.length?`候選庫：${catalogue.length}筆站牌。請核對道路側邊與方向。`:'尚未載入站牌候選庫。請匯入已下載的政府站牌JSON；本版不會要求或保存TDX金鑰。';renderMap();}
function fitMap(){const coords=current().stops.filter(s=>s.coord).map(s=>[s.coord[1],s.coord[0]]);if(coords.length)map.fitBounds(coords,{padding:[65,65],maxZoom:16});else map.setView([24.04,121.61],12);}
function renderMap(){if(!map)return;markers.clearLayers();roadLayers.clearLayers();candidateLayers.clearLayers();const p=current();p.stops.forEach((s,i)=>{if(!s.coord)return;const marker=L.marker([s.coord[1],s.coord[0]],{draggable:true,icon:L.divIcon({className:`station-number ${s.confirmed?'ok':''} ${step==='stops'&&i===selectedStop?'selected':''}`,html:String(i+1),iconSize:[24,24],iconAnchor:[12,12]})}).addTo(markers);marker.bindTooltip(escape(s.name));marker.on('click',()=>{selectedStop=i;setStep('stops');});marker.on('dragend',()=>{const ll=marker.getLatLng();mutate(()=>{invalidateStop(p,s.id);s.coord=[ll.lng,ll.lat];s.coordinateSource='管理者拖曳校正';clearTimes(p);});});});
 p.segments.forEach((s,i)=>{if(!s.path)return;const line=L.polyline(s.path.map(c=>[c[1],c[0]]),{color:s.confirmed?draft.color:'#b59654',weight:step==='roads'&&i===selectedSegment?5:3,opacity:.75,dashArray:s.confirmed?null:'6 5'}).addTo(roadLayers);line.on('click',()=>{selectedSegment=i;setStep('roads');});if(step==='roads'&&i===selectedSegment)for(const [j,c]of s.via.entries())L.circleMarker([c[1],c[0]],{radius:5,color:'#547a95',fillOpacity:1}).bindTooltip('必經點 '+(j+1)).addTo(candidateLayers);});
 if(step==='stops'&&p.stops[selectedStop])for(const [i,c]of candidatesFor(p.stops[selectedStop].name,catalogue).entries()){const marker=L.marker([c.coord[1],c.coord[0]],{icon:L.divIcon({className:'candidate-number',html:String(i+1),iconSize:[20,20],iconAnchor:[10,10]})}).bindTooltip(escape(c.name)+'（候選）').addTo(candidateLayers);marker.on('click',()=>chooseCandidate(c));}
 $('map-instruction').textContent=mode==='stop'?'定位模式：在地圖點選實際站牌位置。':mode==='via'?'必經點模式：依行駛順序點選道路；完成後按「重算此路段」。':step==='stops'?'選候選站牌後請核對；可拖曳站點微調位置。':step==='roads'?'點選左側路段可局部校正。虛線為尚未確認的道路候選。':'站點與道路會隨草稿更新；正式路網不受影響。';}
async function osrm(coords){
 if(coords.length>95)throw Error('控制點過多，請改用局部路段重算');const url='https://router.project-osrm.org/route/v1/driving/'+coords.map(c=>c.join(',')).join(';')+'?overview=full&geometries=geojson&steps=true';
 const cacheKey='p140:osrm:'+url;try{const cached=localStorage.getItem(cacheKey);if(cached)return JSON.parse(cached);}catch{}
 const result=await (routeQueue=routeQueue.catch(()=>{}).then(async()=>{const wait=Math.max(0,1100-(Date.now()-lastRouteRequest));if(wait)await new Promise(r=>setTimeout(r,wait));lastRouteRequest=Date.now();const response=await fetch(url,{signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('道路服務暫時無法使用（HTTP '+response.status+'）；草稿已保留。');const data=await response.json();if(data.code!=='Ok')throw Error('找不到可行道路，請檢查站點與必經點。');return data;}));try{localStorage.setItem(cacheKey,JSON.stringify(result));}catch{}return result;
}
function legsPath(legs){const path=[];for(const leg of legs)for(const st of leg.steps||[])for(const c of st.geometry?.coordinates||[]){if(!path.length||meters(path.at(-1),c)>.01)path.push(c);}if(path.length<2)throw Error('道路回應缺少折線，未變更原資料。');return path;}
async function runBusy(fn){if(busy)return;busy=true;document.querySelectorAll('#route-all,#route-segment').forEach(b=>b.disabled=true);toast('正在產生道路候選，請稍候…');try{await fn();}catch(e){toast(e.name==='TimeoutError'?'道路服務逾時；保留原道路，可稍後重試。':e.message);}finally{busy=false;render();document.querySelectorAll('#route-all,#route-segment').forEach(b=>b.disabled=false);}}
async function routeAll(){const p=current();if(p.stops.length<2||p.stops.some(s=>!validCoord(s.coord)))throw Error('請先定位本方向全部站點');const patternId=p.id,coords=[p.stops[0].coord],counts=[];const signature=JSON.stringify({stops:p.stops.map(s=>[s.id,s.coord]),via:p.segments.map(s=>s.via)});for(let i=0;i<p.segments.length;i++){const via=p.segments[i].via||[];coords.push(...via,p.stops[i+1].coord);counts.push(via.length+1);}const data=await osrm(coords);if(current().id!==patternId||JSON.stringify({stops:p.stops.map(s=>[s.id,s.coord]),via:p.segments.map(s=>s.via)})!==signature)throw Error('站點或方向已改變，未套用舊請求結果');let offset=0;const updates=p.segments.map((s,i)=>{const legs=data.routes[0].legs.slice(offset,offset+counts[i]);offset+=counts[i];return {...s,path:legsPath(legs),durationSec:legs.reduce((n,l)=>n+l.duration,0),confirmed:false,source:'OSRM道路候選（尚未確認）'};});mutate(()=>{p.segments=p.segments.map((s,i)=>s.locked?s:updates[i]);clearTimes(p);});toast('道路候選已產生，請逐段核對後確認。');fitMap();}
async function routeSegment(){const p=current(),index=selectedSegment,s=p.segments[index];if(s.locked)throw Error('請先解除此路段鎖定');const coords=[p.stops[index].coord,...s.via,p.stops[index+1].coord];if(coords.some(c=>!validCoord(c)))throw Error('此路段起訖站尚未定位');const before=JSON.stringify(coords),data=await osrm(coords);if(current()!==p||p.segments[index]!==s||JSON.stringify([p.stops[index].coord,...s.via,p.stops[index+1].coord])!==before)throw Error('路段資料已改變，未套用舊請求結果');const path=legsPath(data.routes[0].legs);mutate(()=>{s.path=path;s.durationSec=data.routes[0].duration;s.confirmed=false;s.source='OSRM道路候選（尚未確認）';clearTimes(p);});toast('已重新產生此路段，其他道路保留。');}
function acceptDraft(next){checkpoint();draft=next;patternIndex=0;selectedStop=0;selectedSegment=0;mode=null;save();render();fitMap();}
function parseImport(text){const obj=JSON.parse(text.replace(/^\s*```(?:json)?\s*/,'').replace(/\s*```\s*$/,''));if(obj.draftVersion)return validateDraftShape(obj);if(obj.recognitionVersion)return fromRecognition(obj);if(obj.schemaVersion)return fromNetwork(obj);throw Error('無法辨識JSON格式，請匯入P140草稿、辨識結果或路線JSON。');}
async function start(){try{
 map=L.map('editor-map',{zoomAnimation:false}).setView([24.04,121.61],12);L.tileLayer('https://wmts.nlsc.gov.tw/wmts/EMAP/default/GoogleMapsCompatible/{z}/{y}/{x}',{maxZoom:19,attribution:'底圖 © <a href="https://maps.nlsc.gov.tw/">國土測繪中心</a> · 道路候選 OSRM / © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);markers=L.layerGroup().addTo(map);roadLayers=L.layerGroup().addTo(map);candidateLayers=L.layerGroup().addTo(map);
 map.on('click',e=>{if(mode==='stop'){const p=current(),s=p.stops[selectedStop];if(!s)return;mutate(()=>{invalidateStop(p,s.id);s.coord=[e.latlng.lng,e.latlng.lat];s.coordinateSource='管理者地圖定位';clearTimes(p);});mode=null;renderMap();}else if(mode==='via'){const p=current(),s=p.segments[selectedSegment];if(!s||s.locked)return;mutate(()=>{s.via.push([e.latlng.lng,e.latlng.lat]);s.path=null;s.durationSec=null;s.confirmed=false;clearTimes(p);});}});
 try{catalogue=normalizeCatalogue(JSON.parse(localStorage.getItem(CATALOGUE)||'null'));}catch{try{catalogue=normalizeCatalogue(await (await fetch('editor-data/stop-catalogue.json')).json());}catch{catalogue=[];}}
 try{const saved=localStorage.getItem(STORAGE);if(saved)draft=validateDraftShape(JSON.parse(saved));}catch{toast('先前草稿無法讀取，已保留於本機，改開啟310待確認草稿。');}
 if(!draft)draft=fromRecognition(await (await fetch('editor-data/310-recognition.json')).json());save();render();fitMap();
 }catch(e){toast('工作台載入失敗：'+e.message);$('save-state').textContent='載入失敗';console.error(e);}}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>setStep(b.dataset.step));$('fit-map').onclick=fitMap;$('dialog-close').onclick=()=>$('studio-dialog').close();$('export-top').onclick=()=>setStep('export');$('validate').onclick=renderValidation;
for(const [id,key]of [['route-short','shortName'],['route-name','name'],['route-id','routeId'],['route-color','color']])$(id).onchange=()=>{if(!$(id).value.trim())return toast('欄位不可空白');mutate(()=>{draft[key]=$(id).value;});};for(const [id,key]of [['source-title','title'],['source-url','url'],['source-date','date'],['source-notes','notes']])$(id).onchange=()=>mutate(()=>{draft.source[key]=$(id).value;},{redraw:false});
$('save-draft').onclick=()=>download(draft.routeId+'_draft.json',draft);$('undo').onclick=()=>{if(!history.length)return;draft=JSON.parse(history.pop());patternIndex=0;selectedStop=0;selectedSegment=0;save();render();$('undo').disabled=!history.length;};
$('load-310').onclick=async()=>{try{acceptDraft(fromRecognition(await (await fetch('editor-data/310-recognition.json')).json()));toast('已載入310官方圖片辨識草稿，所有位置及道路待確認。');}catch(e){toast(e.message);}};
$('load-demo').onclick=async()=>{try{acceptDraft(fromNetwork(await (await fetch('data/bus_network.json')).json()));setStep('stops');toast('已開啟完整合成資料，可測試各編輯步驟；非官方310路線。');}catch(e){toast(e.message);}};$('new-draft').onclick=()=>acceptDraft(blankDraft());
$('import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{acceptDraft(parseImport(await file.text()));toast('匯入完成；可按復原返回上一份草稿。');}catch(e){toast('匯入失敗：'+e.message);}e.target.value='';};
$('import-recognition').onclick=()=>{try{acceptDraft(parseImport($('recognition-text').value));toast('辨識結果已匯入，仍須確認位置、道路與站序。');}catch(e){toast(e.message);}};
$('compare-recognition').onclick=()=>{try{const obj=JSON.parse($('recognition-text').value.replace(/^\s*```(?:json)?\s*/,'').replace(/\s*```\s*$/,''));const{incoming,changes}=compareRecognition(draft,obj);const body=document.createElement('div');body.innerHTML='<p>只更新班次時，保留已校正的位置與道路。站序改變時保留同名站與未受影響路段，清除逐站時間並要求重新確認站序。</p>'+(changes.length?'<ul>'+changes.map(c=>'<li>'+escape(c.type+'：'+c.name+' '+(c.detail||''))+'</li>').join('')+'</ul>':'<p>站序與班次沒有差異。</p>');dialog('新版官方資訊差異',body,[{text:'取消',fn:()=>$('studio-dialog').close()},{text:'套用更新並保留校正',primary:true,fn:()=>{acceptDraft(mergeRecognition(draft,incoming));$('studio-dialog').close();toast('更新已套用，可按復原返回。');}}]);}catch(e){toast(e.message);}};
$('ai-prompt').onclick=async()=>{try{const text=await(await fetch('editor-data/AI_RECOGNITION_PROMPT.md')).text();const area=document.createElement('textarea');area.value=text;area.readOnly=true;area.setAttribute('aria-label','AI辨識提示詞');dialog('複製提示詞，與官方圖片一起交給AI',area,[{text:'下載提示詞',fn:()=>download('P140_AI_Recognition_Prompt.md',text,'text/markdown')},{text:'複製',primary:true,fn:()=>{navigator.clipboard.writeText(text).then(()=>toast('提示詞已複製')).catch(()=>{area.select();toast('請手動複製選取的提示詞');});}}]);}catch(e){toast(e.message);}};
$('catalogue-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const next=normalizeCatalogue(JSON.parse(await file.text()));catalogue=[...next,...catalogue.filter(c=>!next.some(n=>n.id===c.id))];try{localStorage.setItem(CATALOGUE,JSON.stringify(catalogue));}catch{}render();toast('已加入'+next.length+'筆站牌候選。');}catch(e){toast('站牌資料匯入失敗：'+e.message);}e.target.value='';};
$('match-stops').onclick=()=>{const p=current();let proposed=0,ambiguous=0;mutate(()=>{for(const s of p.stops){if(s.confirmed)continue;const matches=candidatesFor(s.name,catalogue).filter(c=>c.score===100);if(matches.length===1&&!s.coord){s.coord=[...matches[0].coord];s.coordinateSource=matches[0].source;s.candidateId=matches[0].id;s.confirmed=false;invalidateStop(p,s.id);proposed++;}else if(matches.length>1)ambiguous++;}if(proposed)clearTimes(p);});fitMap();toast(`已提出${proposed}個唯一同名位置；${ambiguous}站有多個候選，請逐站選擇。`);};
$('add-stop').onclick=()=>ask('新增站名','',name=>mutate(()=>{const p=current();p.stops.push({id:uid('call'),name,coord:null,confirmed:false,coordinateSource:'尚未定位',dwellSec:20,arrivalOffsetSec:null,departureOffsetSec:null});ensureSegments(p);p.sequenceConfirmed=false;clearTimes(p);selectedStop=p.stops.length-1;}));$('confirm-sequence').onclick=()=>{if(current().stops.length<2)return toast('至少需要兩站');mutate(()=>{current().sequenceConfirmed=true;});toast('已確認目前站序；調整順序後需要重新確認。');};
$('route-all').onclick=()=>runBusy(routeAll);$('confirm-roads').onclick=()=>mutate(()=>{for(const s of current().segments)if(s.path)s.confirmed=true;});$('estimate-times').onclick=()=>{try{const factor=Number($('time-factor').value);if(!Number.isFinite(factor)||factor<.2||factor>5)throw Error('調整倍數須為0.2至5');mutate(()=>estimateTimes(current(),factor));toast('逐站估算已產生，請核對合理性；不是官方到站時間。');}catch(e){toast(e.message);}};
$('add-trip').onclick=()=>{try{const time=$('departure-time').value;parseTime(time);const days=[...$('departure-days').querySelectorAll('input:checked')].map(i=>+i.value);if(!days.length)throw Error('至少勾選一個星期');if(current().departures.some(t=>parseTime(t.time)===parseTime(time)&&t.days.some(d=>days.includes(d))))throw Error('此時間的適用星期已有班次');mutate(()=>current().departures.push({id:uid('trip'),time,days}));}catch(e){toast(e.message);}};
$('preview').onclick=()=>{try{const n=exportNetwork(draft,{strict:false});localStorage.setItem(PREVIEW,JSON.stringify(n));const opened=window.open('preview.html','p140-editor-preview');if(!opened)toast('瀏覽器阻擋預覽視窗，請允許本站開啟新分頁。');else toast('已開啟草稿預覽；正式路網沒有變更。');}catch(e){dialog('尚不能播放此草稿',e.message);}};
$('export-json').onclick=()=>{try{const n=exportNetwork(draft,{strict:true});download(draft.routeId+'.json',n);toast('已下載單一路線JSON，正式路網尚未變更。');}catch(e){dialog('資料尚未完成',e.message);}};
$('merge-files').onchange=async e=>{try{const files=[...e.target.files];if(!files.length)return;let routes=[],versions=[];for(const f of files){const n=JSON.parse(await f.text()),errors=validateNetwork(n);if(errors.length)throw Error(f.name+'：'+errors[0]);routes.push(...n.routes);versions.push(n.schemaVersion);}if(versions.some(v=>v!=='1.0.0'))throw Error('格式版本不符');const n={schemaVersion:'1.0.0',dataVersion:'merged-'+new Date().toISOString().slice(0,10),timezone:'Asia/Taipei',generatedAt:new Date().toISOString().slice(0,10),isDemo:routes.some(r=>r.isDemo),displaySettings:{stopLabelBeforeArrivalSec:30,stopLabelAfterDepartureSec:15},routes};const errors=validateNetwork(n);if(errors.length)throw Error(errors[0]);download('bus_network.json',n);$('merge-status').textContent=`已合併${routes.length}條路線；下載完成後再部署。`;}catch(e){$('merge-status').textContent='合併失敗：'+e.message;}e.target.value='';};
$('source-image-upload').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>3*1024*1024)return toast('來源圖片請小於3MB；大圖可保留在電腦，草稿只記錄來源名稱。');const reader=new FileReader();reader.onload=()=>{mutate(()=>{draft.source.images.push(reader.result);});toast('來源圖片已加入草稿；請另存官方原始檔作備份。');};reader.readAsDataURL(file);e.target.value='';};
window.addEventListener('load',start,{once:true});
